# "above data, list all pairs of user IDs (no duplicate pairs, list lower ID first) such that one user has at least two instances with location and at least one instance with entity, and the other user has exactly one instance with description and abstract concept and exactly one instance with abbreviation. Each of the questions can be labelled as one of the labels (the data does not provide the labels, you need to figure out the label from the semantics of the question): description and abstract concept, entity, human being, numeric value, location, abbreviation. In your answer, list all pairs in the format (user_id_1, user_id_2), separated by newlines."

# We need to:
# 1. Assign a label to each question instance based on its semantics.
# 2. For each user, count how many instances they have for each label.
# 3. Find pairs (u1, u2) where:
#    - u1 has ≥2 "location" and ≥1 "entity"
#    - u2 has exactly 1 "description and abstract concept" and exactly 1 "abbreviation"
# 4. Output all such pairs, with lower ID first, no duplicates.

# Let's start by defining a function to label each question.

# Labels:
# - description and abstract concept: questions asking for definitions, meanings, explanations
# - entity: questions asking for a specific thing (person, place, thing)
# - human being: a person (e.g., "Who was Picasso?")
# - numeric value: questions asking for numbers
# - location: questions asking for places
# - abbreviation: questions asking for what an acronym stands for

# We'll use keyword and pattern matching to assign labels.

def assign_label(instance):
    instance_lower = instance.lower()

    # Check for abbreviations (e.g., "What does CNN stand for?")
    if any(word in instance_lower for word in ['stand for', 'mean', 'abbreviation', 'acronym']):
        if any(word in instance_lower for word in ['what does', 'what is the meaning of']):
            return "abbreviation"

    # Check for description/abstract concept (definitions, meanings, explanations)
    if any(word in instance_lower for word in ['what is', 'define', 'meaning', 'describe', 'explain', 'how does']):
        if any(word in instance_lower for word in ['mean', 'stand for', 'acronym', 'abbreviation']):
            return "abbreviation"  # prioritize over description
        if any(word in instance_lower for word in ['how', 'why', 'what is the', 'what does']):
            return "description and abstract concept"

    # Check for entity (specific thing)
    if any(word in instance_lower for word in ['who', 'what', 'where', 'when', 'which']):
        if any(word in instance_lower for word in ['is', 'was', 'are', 'were']):
            # "Who was Picasso?" → human being
            if any(word in instance_lower for word in ['who was', 'who is', 'who are']):
                return "human being"
            # "Where is Glasgow?" → location
            if any(word in instance_lower for word in ['where is', 'where are', 'where was', 'where were']):
                return "location"
            # "What is the C programming language?" → description or entity
            if any(word in instance_lower for word in ['what is', 'what are']):
                if any(word in instance_lower for word in ['the', 'a', 'an']):
                    return "entity"
                else:
                    return "description and abstract concept"
            # "What does CPR stand for?" → abbreviation
            if any(word in instance_lower for word in ['what does', 'what is the']):
                if any(word in instance_lower for word in ['stand for', 'mean']):
                    return "abbreviation"
            # "What is the capital of California?" → location
            if any(word in instance_lower for word in ['capital', 'city', 'town', 'province', 'state', 'country']):
                return "location"
            # "What is the name of the game?" → entity
            if any(word in instance_lower for word in ['name', 'title', 'nickname', 'moniker']):
                return "entity"
            # "How many islands does Fiji have?" → numeric value
            if any(word in instance_lower for word in ['how many', 'how much', 'how long', 'how old']):
                return "numeric value"
            # "What country is Mount Everest in?" → location
            if any(word in instance_lower for word in ['country', 'state', 'province', 'territory']):
                return "location"
            # "What does the T.S. stand for in T.S. Eliot's name?" → abbreviation
